#include "lcd_ui.h"
#include "lcd.h"
void lcd_ui_person_wait(void){lcd_show_lines("WAITING PERSON","COME CLOSER");}void lcd_ui_hello(void){lcd_show_lines("HELLO!","SELECT USER");}void lcd_ui_user_select(void){lcd_show_lines("RIGHT:CUSTOMER","LEFT:RIDER");}void lcd_ui_customer(void){lcd_show_lines("CUSTOMER MODE","SCAN PRODUCT");}void lcd_ui_rider(void){lcd_show_lines("RIDER MODE","SCAN PACKAGE");}void lcd_ui_ir_wait(void){lcd_show_lines("SCAN BLACK TAPE","WITH IR SENSOR");}void lcd_ui_product_select(void){lcd_show_lines("PRODUCT FOUND","SELECT A/B/C");}void lcd_ui_a_added(void){lcd_show_lines("A SELECTED","PLEASE WAIT 2S");}void lcd_ui_b_added(void){lcd_show_lines("B SELECTED","PLEASE WAIT 2S");}void lcd_ui_c_added(void){lcd_show_lines("C SELECTED","PLEASE WAIT 2S");}void lcd_ui_next_or_done(void){lcd_show_lines("SCAN NEXT ITEM","OR PRESS DONE");}void lcd_ui_total(void){lcd_show_lines("TOTAL ITEMS","CHECK FND");}void lcd_ui_payment_done(void){lcd_show_lines("PAYMENT DONE","THANK YOU");}void lcd_ui_rider_done(void){lcd_show_lines("PICKUP DONE","THANK YOU");}void lcd_ui_reset(void){lcd_show_lines("SYSTEM RESET","WAITING PERSON");}void lcd_ui_remove_old_item(void){lcd_show_lines("REMOVE OLD ITEM","FROM IR SENSOR");}
